"부기장 임무를 맡게 되어 영광입니다, 선장님. 입항과 임무 소식은 제가 직접 보고드리겠습니다.":"C'est un honneur d'être votre second, Capitaine. Je vous ferai moi-même le rapport des accostages et des missions.",
"항해장":"Navigateur",
"항로·보급·연료 경고 등 항해 전반을 보고한다":"Rapports de navigation : routes, ravitaillement, alertes carburant",
"항해장을 맡겠습니다. 항로와 보급, 연료 상황은 저에게 맡겨 주십시오.":"Je prends le poste de navigateur. Routes, ravitaillement, carburant : laissez-moi faire.",
"기관장":"Chef mécanicien",
"엔진·탱크·수리를 책임지고 고장을 보고한다":"Responsable des moteurs, réservoirs et réparations ; signale les pannes",
"기관실은 제가 책임지겠습니다. 엔진 소리만 들어도 상태를 압니다, 선장님.":"La salle des machines, j'en fais mon affaire. Rien qu'au bruit du moteur, je connais son état, Capitaine.",
"갑판장":"Officier tactique",
"함포와 전투 대원을 지휘하고 전투 결과를 보고한다":"Commande les canons et les combattants ; rapporte l'issue des combats",
"갑판장으로서 이 함선을 지키겠습니다. 적이 나타나면 제가 먼저 나서겠습니다.":"En tant qu'officier tactique, je défendrai ce vaisseau. Si l'ennemi se montre, je serai en première ligne.",
"과학장":"Officier scientifique",
"천체 발견·신호 분석·유적 조사를 보고한다":"Rapports de découvertes d'astres, d'analyses de signaux et de fouilles de ruines",
"과학장을 맡게 되어 기쁩니다! 새로운 천체를 발견하면 가장 먼저 알려 드리겠습니다.":"Ravi d'être votre officier scientifique ! Dès qu'un nouvel astre apparaît, vous serez le premier informé.",
"화물장":"Quartier-maître",
"표류물·난파선·화물 회수를 맡아 보고한다":"Gère la récupération des objets à la dérive, des épaves et du fret",
"화물장입니다. 우주에 떠도는 것은 무엇이든 건져서 창고에 채워 넣겠습니다.":"Quartier-maître à votre service. Tout ce qui dérive dans l'espace finira repêché et rangé en soute.",
"군의관":"Médecin de bord",
"선체 피해와 산소, 승무원의 건강과 사기를 살핀다":"Veille sur la coque, l'oxygène, la santé et le moral de l'équipage",
"군의관을 맡겠습니다. 승무원들의 건강과 사기는 제가 챙기겠습니다, 선장님.":"Je serai votre médecin de bord. La santé et le moral de l'équipage, je m'en charge, Capitaine.",
