"<b>{0}</b>에 처음 입항했습니다, 선장님. {1} 이곳의 특산품은 <b>{2}</b>, 비싸게 사 주는 것은 <b>{3}</b>입니다. <span class=\"acc\">(🔬+{4})</span>":"Premier accostage à <b>{0}</b>, Capitaine. {1} La spécialité locale : <b>{2}</b>. On y achète au prix fort : <b>{3}</b>. <span class=\"acc\">(🔬+{4})</span>",
