"- 산소가 바닥났습니다 -":"- L'oxygène est épuisé -",
" (운항하던 항로는 닫힙니다)":" (ses routes en service sont fermées)",
"기함 <b>「{0}」</b>은(는) 돌아오지 못했습니다. 싣고 있던 화물도 함께 사라졌습니다.<br>\n      구조선이 승무원들을 고향 <b>지구</b>로 데려왔습니다.<br>\n      남은 함선 <b>{1}척</b> 가운데 <b>「{2}」</b>이(가) 새 기함이 됩니다{3}.<br>\n      <b>승무원·크레딧·연구·발견 기록은 그대로입니다.</b>":"Le vaisseau amiral <b>« {0} »</b> n'est pas revenu. Sa cargaison a disparu avec lui.<br>\n      Un vaisseau de secours a ramené l'équipage sur sa <b>Terre</b> natale.<br>\n      Parmi les <b>{1}</b> vaisseaux restants, <b>« {2} »</b> devient le nouveau vaisseau amiral{3}.<br>\n      <b>Équipage, crédits, recherches et découvertes sont conservés.</b>",
"지구에서 다시 시작":"Repartir de la Terre",
"마지막 함선 <b>「{0}」</b>마저 파괴되었습니다.<br>\n      더는 띄울 배가 없습니다. 함대는 여기서 끝났습니다.<br>\n      <b>모든 진행을 잃고 처음부터 다시 시작합니다.</b>":"Le dernier vaisseau, <b>« {0} »</b>, a été détruit à son tour.<br>\n      Il ne reste plus rien à faire décoller. La flotte s'arrête ici.<br>\n      <b>Toute la progression est perdue : il faut tout recommencer.</b>",
"처음부터 다시 시작":"Tout recommencer",
"🛟 지구로 귀환했습니다. 새 기함 「{0}」의 출항 준비를 마쳤습니다":"🛟 Retour sur Terre. Le nouveau vaisseau amiral « {0} » est prêt à appareiller",
"지구를 떠난 지 <b>{0}일</b>.<br>\n    당신의 함선은 마침내 시간과 공간이 시작된 한 점에 닿았습니다.<br>\n    발견한 천체 <b>{1}/{2}</b> · 전투 승리 <b>{3}</b>회 ·\n    함께한 승무원 <b>{4}</b>명<br><br>\n    모든 별과 은하, 그리고 우리 자신이 바로 이 빛에서 태어났습니다.<br>\n    <b>항해는 끝나지 않습니다.</b> 아직 발견하지 못한 우주가 기다립니다.":"<b>{0} jours</b> depuis le départ de la Terre.<br>\n    Votre vaisseau a enfin atteint le point où le temps et l'espace ont commencé.<br>\n    Astres découverts <b>{1}/{2}</b> · Combats gagnés <b>{3}</b> ·\n    Compagnons d'équipage <b>{4}</b><br><br>\n    Chaque étoile, chaque galaxie, et nous-mêmes, sommes nés de cette lumière.<br>\n    <b>Le voyage ne s'achève pas.</b> Un univers encore inexploré vous attend.",
"🎯 임무 완료: {0} (+{1}💠{2})":"🎯 Mission accomplie : {0} (+{1}💠{2})",
"🏅 업적 달성: 「{0}」 (+{1}💠) - 도감에서 칭호 장착 가능":"🏅 Succès débloqué : « {0} » (+{1}💠) - titre à équiper dans le Codex",
