" (토벌됨)":" (rasée)",
" · 전투력 {0}":" · puissance {0}",
"🔒 {0} - 워프 드라이브 Mk.{1} 필요":"🔒 {0} - Moteur de distorsion Mk.{1} requis",
"🌠 <b>중력 가속</b>":"🌠 <b>Accélération gravitationnelle</b>",
"🔧 <b>엔진 이상</b>":"🔧 <b>Avarie moteur</b>",
" {0}일":" {0} j",
"🌬 중력류 <b>{0}{1}%</b>":"🌬 Courant de gravité <b>{0}{1} %</b>",
"🎯 모든 임무 완료 - 자유 항해":"🎯 Toutes les missions accomplies - navigation libre",
"궤도 왕복용으로 쓰이던 퇴역 셔틀. 낡았지만 모든 선장의 첫 배는 언제나 이런 배다.":"Une navette réformée qui faisait la liaison avec l'orbite. Usée, mais le premier vaisseau de tout capitaine ressemble toujours à ça.",
"정거장 사이에서 화물을 끌던 작업선. 작지만 힘이 좋고 연비가 준수하다.":"Un engin de servitude qui tractait le fret entre les stations. Petit, mais costaud et plutôt sobre.",
"엔진 위에 컨테이너를 얹은 게 전부인 화물선. 느리지만 일반 등급에서 가장 많이 싣는다.":"Des conteneurs posés sur un moteur, et rien d'autre. Lent, mais c'est lui qui charge le plus en rang Commun.",
"무인 탐사선을 유인용으로 개조했다. 가볍고 빠르며 한 번 보급으로 멀리 간다.":"Une sonde inhabitée convertie en vaisseau habité. Légère, rapide, elle va loin avec un seul plein.",
"후퇴익을 단 소형 전투함. 속도와 무장의 균형이 좋아 초보 선장의 사랑을 받는다.":"Un petit bâtiment de combat aux ailes en flèche. Son équilibre entre vitesse et armement séduit les jeunes capitaines.",
"함수의 굴착 드릴로 소행성을 파내는 채굴선. 선체가 두껍고 화물칸이 넓다.":"Un vaisseau minier qui creuse les astéroïdes avec sa foreuse de proue. Coque épaisse, vaste soute.",
"밀수꾼들이 애용하던 바늘 모양 쾌속선. 고급 등급에서 가장 빠르다.":"Un bolide en forme d'aiguille, chéri des contrebandiers. Le plus rapide du rang Avancé.",
"화물 모듈 세 칸을 줄줄이 매단 장거리 수송선. 별과 별 사이를 묵묵히 오간다.":"Un transport long-courrier traînant trois modules de fret à la file. Il va d'étoile en étoile sans broncher.",
"전진익과 측면 함포를 갖춘 주력 전투함. 해적들이 가장 마주치기 싫어하는 배.":"Bâtiment de combat principal, à ailes en flèche inversée et canons de flanc. Celui que les pirates redoutent le plus de croiser.",
"컨테이너 네 열을 싣는 초대형 화물선. 희귀 등급 최고의 적재량을 자랑한다.":"Un cargo géant à quatre rangées de conteneurs. La plus grande capacité du rang Rare.",
"거대한 태양 돛으로 항성풍을 타는 쾌속선. 연료를 거의 쓰지 않고 우아하게 미끄러진다.":"Un voilier rapide qui chevauche le vent stellaire avec son immense voile solaire. Il glisse avec élégance, presque sans carburant.",
"원반형 선체에 관측 장비를 가득 실은 연구선. 행운이 따르는 배로 유명하다.":"Un navire de recherche à coque discoïdale, bourré d'instruments d'observation. Réputé pour porter chance.",
"황금빛 합금으로 두른 전설적인 무역선. 이 배가 입항하면 시장의 시세가 움직인다.":"Un vaisseau marchand de légende, habillé d'un alliage doré. Quand il accoste, les cours du marché bougent.",
"겹겹의 장갑판과 포탑으로 무장한 전함. 영웅 등급에서 가장 단단한 선체를 가졌다.":"Un cuirassé bardé de plaques de blindage et de tourelles. La coque la plus solide du rang Épique.",
"반투명한 선체가 별빛에 스며드는 유령선. 누가 만들었는지 아무도 모른다.":"Un vaisseau fantôme dont la coque translucide se fond dans la lumière des étoiles. Nul ne sait qui l'a construit.",
"부채꼴 돛으로 항성의 빛을 모아 달리는 채집선. 태양의 축복을 받았다고 전해진다.":"Un collecteur qui file en captant la lumière des étoiles avec ses voiles en éventail. On le dit béni par le Soleil.",
"수천 명이 대를 이어 살아가도록 설계된 세대 우주선. 하나의 도시가 통째로 항해한다.":"Un vaisseau-génération conçu pour abriter des milliers de personnes, de génération en génération. Une ville entière en voyage.",
"공간 자체를 접어 도약하는 차원함. 지나간 자리에는 푸른 빛의 파문만 남는다.":"Un bâtiment dimensionnel qui saute en repliant l'espace lui-même. Sur son passage ne reste qu'une onde de lumière bleue.",
