"직위에 임명된 승무원만 능력을 온전히 발휘합니다. <b>높은 직위일수록 능력이 크게</b> 적용되고, 직위마다 고유 효과가 따로 붙습니다. 임명되지 않은 승무원은 능력의 {0}%만 발휘합니다.":"Seuls les membres nommés à un poste donnent toute leur mesure. <b>Plus le poste est élevé, plus leur talent pèse</b>, et chaque poste ajoute son propre effet. Sans poste, un membre n'exprime que {0} % de son talent.",
