"📍 기지 입항 시 드물게 만남 · 영입 비용 <b>{0}</b>💠":"📍 Rencontre rare en accostant dans une base · Coût <b>{0}</b>💠",
"💞 호감도":"💞 Affinité",
"호감도는 직위에 임명한 채 항해하면 오르고, 능력을 최대 <b>+50%</b>까지 키웁니다 (지금 <b>×{0}</b>)":"L'affinité grimpe en naviguant avec un poste attribué et renforce le talent jusqu'à <b>+50 %</b> (actuellement <b>×{0}</b>)",
"🔒 호감도 80에 이르면 특별한 이야기와 선물이 열립니다":"🔒 À 80 d'affinité, un épisode spécial et un cadeau se débloquent",
"대기 {0}":"Réserve {0}",
" - 지금 적용 중: 기본 × 호감도 {0} × {1}":" - appliqué actuellement : base × affinité {0} × {1}",
