"세부 능력{0}":"Talents détaillés{0}",
"직위별 능력 - 높은 직위일수록 크게 발휘됩니다":"Talent selon le poste - plus le poste est élevé, plus il compte",
"<span class=\"acc\" style=\"font-size:11px\">현재</span>":"<span class=\"acc\" style=\"font-size:11px\">Actuel</span>",
"💤 대기":"💤 Réserve",
"← 승무원 창으로":"← Retour à l'équipage",
"💞 승무원 상세":"💞 Fiche d'équipage",
"아직 재생 전 (화면을 한 번 누르면 시작)":"Pas encore de lecture (touchez l'écran une fois pour lancer)",
"🔊 소리·화면 효과 설정":"🔊 Réglages son et effets visuels",
"전체 소리":"Son général",
"지금 흐르는 곡: <b>{0}</b>":"En cours de lecture : <b>{0}</b>",
"🔇 꺼짐":"🔇 Coupé",
"🔊 켜짐":"🔊 Activé",
"배경 음악":"Musique",
"효과음":"Effets sonores",
"배경 음악은 지금 있는 우주에 따라 바뀌고, 전투 중에는 긴박한 곡으로 넘어갑니다. 모든 소리는 실시간으로 합성되어 음악 파일이 없습니다.":"La musique change selon l'univers où vous êtes et laisse place à un morceau haletant en combat. Tous les sons sont synthétisés en temps réel : il n'y a aucun fichier audio.",
"화면 효과":"Effets visuels",
"📳 화면 흔들림 세기":"📳 Intensité des secousses d'écran",
"⚡ 번쩍임":"⚡ Flashs",
"피격·워프 때 화면이 번쩍입니다. 눈이 피로하면 줄이세요.":"L'écran flashe lors des impacts et des sauts en distorsion. Réduisez si vos yeux fatiguent.",
"보통":"Normal",
"약하게":"Faible",
"효과음 들어보기":"Écouter les effets sonores",
