"<b>우주를 탭</b>하면 그곳으로 항해합니다. 지도는 위로 갈수록 더 멀고 더 오래된 우주입니다.<br>\n출항할 때마다 <b>연료와 산소</b>가 자동 보급되고, 항해 중 소모됩니다.<br>\n천체를 <b>발견</b>해 연구 데이터를 모으고 <b>워프 드라이브</b>를 연구해 다음 우주로 나아가세요.<br>\n기지에서 <b>무역</b>으로 돈을 벌고, <b>승무원</b>을 영입하고, <b>해적</b>을 물리치세요.<br>\n최종 목적지는 138억 년 전, <b>우주의 시작</b>입니다.":"<b>Touchez l'espace</b> pour y faire route. Plus on monte sur la carte, plus l'univers est lointain et ancien.<br>\nÀ chaque départ, le <b>carburant et l'oxygène</b> sont ravitaillés automatiquement, puis consommés en route.<br>\n<b>Découvrez</b> des astres pour amasser des données de recherche, puis recherchez le <b>Moteur de distorsion</b> pour gagner l'univers suivant.<br>\nDans les bases, enrichissez-vous par le <b>commerce</b>, recrutez un <b>équipage</b> et repoussez les <b>pirates</b>.<br>\nDestination finale : il y a 13,8 milliards d'années, le <b>commencement de l'univers</b>.",
