"⚔️ 결투를 받아들인다 (전투력 {0} · 승리 시 💎)":"⚔️ Accepter le duel (puissance {0} · 💎 en cas de victoire)",
"💰 돈으로 해결한다 (−{0}💠)":"💰 Régler ça en payant (−{0}💠)",
