"플라스마 뱀":"Serpent de plasma",
"불타는 몸뚱이가 함선 둘레를 휘감듯 돌고 있습니다. 비늘마다 번개가 튑니다.":"Son corps embrasé tourne autour du vaisseau comme pour l'enlacer. Des éclairs jaillissent de chaque écaille.",
"별벌레 떼":"Essaim de vers stellaires",
