"신호가 겹치며 항법 장치가 하루 동안 먹통이 됐습니다. 화면 속의 '우리'는 사라졌습니다.":"Les signaux se sont superposés et le système de navigation est resté hors service une journée. Le 'nous' de l'écran a disparu.",
